def word_break(s: str, words: list[str]) -> bool:
    """Return True if s can be segmented into a sequence of one or more
    words from `words` (words may be reused). The empty string returns True."""
    if s == "":
        return True

    # Ignore empty strings in the word list; they would not help segmentation.
    word_set = {w for w in words if w}
    if not word_set:
        return False

    max_len = max(len(w) for w in word_set)
    n = len(s)

    # dp[i] is True if s[:i] can be broken into valid words.
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(n):
        if not dp[i]:
            continue
        upper = min(n, i + max_len)
        for j in range(i + 1, upper + 1):
            if s[i:j] in word_set:
                dp[j] = True

    return dp[n]
```

