def eval_rpn(tokens: list[str]) -> int:
    stack: list[int] = []
    operators = {"+", "-", "*", "/"}

    for token in tokens:
        if token in operators:
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            else:  # "/"
                # Truncate toward zero (Python's // rounds toward -inf)
                quotient = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    quotient = -quotient
                stack.append(quotient)
        else:
            stack.append(int(token))

    return stack[0]
```

